#include <string>
#include <string_view>

class Ticket
{
public:
    Ticket(std::string_view event, int priceCents);

    int number() const { return m_number; }
    int price() const { return m_price; }
    static int issued();

    friend bool sameEvent(const Ticket& a, const Ticket& b);

private:
    static inline int s_issued{ 0 };
    std::string m_event{};
    int m_price{};
    int m_number{};
};

Ticket::Ticket(std::string_view event, int priceCents)
    : m_event{ event }, m_price{ priceCents }, m_number{ ++s_issued }
{
}

int Ticket::issued()
{
    return s_issued;
}

bool sameEvent(const Ticket& a, const Ticket& b)
{
    return a.m_event == b.m_event;
}

unitTests:
TEST("numbers count up and issued() keeps track") {
    const int before{ Ticket::issued() };
    const Ticket a{ "Concert", 4500 };
    const Ticket b{ "Concert", 4500 };
    const Ticket c{ "Play", 3000 };
    CHECK_EQ(a.number(), before + 1);
    CHECK_EQ(b.number(), before + 2);
    CHECK_EQ(c.number(), before + 3);
    CHECK_EQ(Ticket::issued(), before + 3);
}
TEST("price") { CHECK_EQ(Ticket("Fair", 800).price(), 800); }
TEST("sameEvent sees the private name") { const Ticket a{ "Concert", 1 }, b{ "Concert", 2 }, c{ "Play", 1 }; CHECK(sameEvent(a, b)); CHECK(!sameEvent(a, c)); }

